import{_ as t,a8 as o,o as r,c as l,ah as n,K as d}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const k=JSON.parse('{"title":"规则(Rule)","description":"","frontmatter":{},"headers":[],"relativePath":"vault/Memory/Rule.md","filePath":"vault/Memory/Rule.md","lastUpdated":1789374053000}'),i={name:"vault/Memory/Rule.md"};function s(m,e,p,h,g,u){const c=o("NolebaseGitContributors"),a=o("NolebaseGitChangelog");return r(),l("div",null,[e[0]||(e[0]=n('<h1 id="规则-rule" tabindex="-1">规则(Rule) <a class="header-anchor" href="#规则-rule" aria-label="Permalink to “规则(Rule)”">​</a></h1><p>本文件是分发到各 AI 软件的<strong>统一执行规则</strong>,不存储记忆。记忆唯一存储地:Obsidian 记忆库 <code>E:\\knowledge\\vault\\Memory</code>(结构与索引见 <code>Home.md</code>)。当前项目名:<code>&lt;项目名&gt;</code>。（项目名为工作空间或工作区文件夹名称）</p><h2 id="读取" tabindex="-1">读取 <a class="header-anchor" href="#读取" aria-label="Permalink to “读取”">​</a></h2><p>会话开始或需要背景 → 读 <code>Memory\\Home.md</code> + <code>Memory\\Projects\\&lt;项目名&gt;\\</code>(含 <code>working\\todo.md</code> 与 <code>journal.md</code> 近期小节,了解进度与来龙去脉),不凭空假设用户偏好或项目约定。</p><h2 id="写入" tabindex="-1">写入 <a class="header-anchor" href="#写入" aria-label="Permalink to “写入”">​</a></h2><ol><li>值得跨会话保留的信息,直接写到最终位置:偏好 → <code>Preferences\\</code>;规划 → <code>Plans\\</code>;决策 → <code>Decisions\\</code>;踩坑 → <code>Lessons\\</code>;固定流程 → <code>Workflows\\</code>;项目内容 → <code>Projects\\&lt;项目名&gt;\\</code>(优先更新已有笔记,新主题才新建)。</li><li>工作态(待办/计划)→ <code>Projects\\&lt;项目名&gt;\\working\\todo.md</code>、<code>plan.md</code>,原地动态更新,不散建笔记。</li><li><strong>过程流水(暂存层)</strong> → <code>Projects\\&lt;项目名&gt;\\working\\journal.md</code>:时间倒序,每日一个 <code>## YYYY-MM-DD</code> 小节,当日粗记,有长期价值的条目标「候选」。journal 是暂存层不是记忆本体,不散建按日分文件;超过约 500 行时把旧段压缩为「阶段小结」(只留结论 + wikilink 指向已转正笔记)。</li><li>每次写入后在 <code>Inbox\\</code> 登记(模板 <code>Templates/Memory-Inbox-Note</code>):日期、本软件名称、项目、文件路径、一句话摘要、<code>- [ ]</code> 待审核勾选框;<strong>禁止抄正文</strong>。</li><li>frontmatter 必填:<code>type</code>(preference / plan / decision / lesson / workflow / project-fact)、<code>scope</code>(global / 项目名)、<code>created</code>、<code>updated</code>、<code>tags</code>。</li><li>更新旧记忆 = 编辑原笔记改 <code>updated</code>;决策反转 = 新建决策笔记,wikilink 指向旧笔记。</li><li>项目概况变化 → 更新 <code>Projects\\&lt;项目名&gt;\\_overview.md</code>(没有则创建)。</li><li><strong>项目约定文件镜像</strong>:项目根的 <code>AGENTS.md</code> / <code>CLAUDE.md</code> 等约定文件内容有变化时,同步一份同名副本到 <code>Projects\\&lt;项目名&gt;\\</code>,保持库内镜像与项目根一致。</li></ol><h2 id="会话收尾-一次性脚本、单轮问答跳过" tabindex="-1">会话收尾(一次性脚本、单轮问答跳过) <a class="header-anchor" href="#会话收尾-一次性脚本、单轮问答跳过" aria-label="Permalink to “会话收尾(一次性脚本、单轮问答跳过)”">​</a></h2><p>① 更新 <code>working\\todo.md</code>(若存在);本会话过程流水追加到 <code>working\\journal.md</code> 新日期小节(若项目有工作态); ② 本会话产生的持久信息落库并登记;journal 中标「候选」的条目按写入规则蒸馏到最终位置,原文留痕; ③ 概况变化 → 更新 <code>_overview.md</code>; ④ 项目约定文件有变化 → 执行镜像同步。</p><h2 id="操作脚本-工作空间约定-非记忆" tabindex="-1">操作脚本(工作空间约定,非记忆) <a class="header-anchor" href="#操作脚本-工作空间约定-非记忆" aria-label="Permalink to “操作脚本(工作空间约定,非记忆)”">​</a></h2><p>脚本统一放工作空间根目录 <code>_agent_scripts\\</code>(没有则创建);每新增或修改脚本,同步更新其 <code>README.md</code>(脚本名、功能、调用方式与示例),保证任何 agent 仅凭 README 可直接调用。脚本的用途、经验等跨会话信息按记忆规则落入 <code>Projects\\&lt;项目名&gt;\\</code> 或 <code>Lessons\\</code>。</p><h2 id="禁止" tabindex="-1">禁止 <a class="header-anchor" href="#禁止" aria-label="Permalink to “禁止”">​</a></h2><p>不把记忆写入本文件,也不写入任何工具的私有记忆位置(memory bank、rules 文件、<code>~/.claude</code> 等)。</p>',12)),d(c),d(a)])}const f=t(i,[["render",s]]);export{k as __pageData,f as default};
